) -> None:
    if reactor_pytest != "asyncio":
        runner = CrawlerRunner(
            settings={
                "TWISTED_REACTOR": "twisted.internet.asyncioreactor.AsyncioSelectorReactor",
            }
        )
        with pytest.raises(
